import{_ as e,c as a,o as l,a3 as r,j as o,aB as n,aC as i}from"./chunks/framework.MI-M1z4O.js";const y=JSON.parse('{"title":"컬렉션 관리 및 일괄 실행","description":"여러 개의 단위 시나리오를 묶어 순차 또는 병렬로 일괄 실행하는 SyncETA 컬렉션 구성 가이드입니다.","frontmatter":{"title":"컬렉션 관리 및 일괄 실행","description":"여러 개의 단위 시나리오를 묶어 순차 또는 병렬로 일괄 실행하는 SyncETA 컬렉션 구성 가이드입니다.","head":[["meta",{"name":"keywords","content":"SyncETA, 컬렉션, 일괄 실행, 크로스 브라우징, 시나리오 묶음 실행, 테스트 스위트"}],["meta",{"property":"og:title","content":"컬렉션 관리 및 일괄 실행 | SyncETA"}],["meta",{"property":"og:description","content":"단위 시나리오들을 그룹화하여 순차 또는 병렬로 실행하는 컬렉션 관리 가이드입니다."}],["link",{"rel":"canonical","href":"https://doc.empasy.com/synceta/collection"}]],"sort":500},"headers":[],"relativePath":"synceta/collection.md","filePath":"ko/synceta/collection.md","lastUpdated":1795045877000}'),s={name:"synceta/collection.md"};function d(c,t,h,g,p,_){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="컬렉션-관리-및-일괄-실행" tabindex="-1">컬렉션 관리 및 일괄 실행 <a class="header-anchor" href="#컬렉션-관리-및-일괄-실행" aria-label="Permalink to “컬렉션 관리 및 일괄 실행”">​</a></h1><p><strong>&#39;컬렉션(Collection)&#39;</strong>은 연관된 복수의 테스트 시나리오를 그룹화하여 하나의 테스트 스위트(Test Suite) 단위로 관리하고 일괄 실행하는 기능입니다.</p><hr><h2 id="_1-컬렉션의-주요-용도" tabindex="-1">1. 컬렉션의 주요 용도 <a class="header-anchor" href="#_1-컬렉션의-주요-용도" aria-label="Permalink to “1. 컬렉션의 주요 용도”">​</a></h2><ul><li><strong>엔드투엔드 시나리오 일괄 순차 실행</strong>: 로그인 -&gt; 상품 탐색 -&gt; 주문 결제 -&gt; 주문 취소와 같은 개별 시나리오를 연속해서 순차적으로 검증합니다.</li><li><strong>다중 브라우저 동시 병렬 실행</strong>: 동일한 시나리오 세트를 Chrome, Firefox, Edge 등 여러 브라우저 환경에서 동시에 병렬 구동하여 크로스 브라우징 호환성을 점검합니다.</li></ul><hr><h2 id="_2-컬렉션-생성-절차" tabindex="-1">2. 컬렉션 생성 절차 <a class="header-anchor" href="#_2-컬렉션-생성-절차" aria-label="Permalink to “2. 컬렉션 생성 절차”">​</a></h2><h3 id="_1단계-컬렉션-메뉴-이동-및-신규-생성" tabindex="-1">1단계: 컬렉션 메뉴 이동 및 신규 생성 <a class="header-anchor" href="#_1단계-컬렉션-메뉴-이동-및-신규-생성" aria-label="Permalink to “1단계: 컬렉션 메뉴 이동 및 신규 생성”">​</a></h3><p>좌측 메뉴의 <strong>&#39;컬렉션&#39;</strong>으로 이동한 후 우측 상단의 <strong>&#39;새로운 컬렉션&#39;</strong> 버튼을 클릭합니다.</p><p><img src="'+n+'" alt="컬렉션 생성 메뉴" loading="lazy"></p><h3 id="_2단계-포함할-시나리오-및-실행-순서-선택" tabindex="-1">2단계: 포함할 시나리오 및 실행 순서 선택 <a class="header-anchor" href="#_2단계-포함할-시나리오-및-실행-순서-선택" aria-label="Permalink to “2단계: 포함할 시나리오 및 실행 순서 선택”">​</a></h3><p>컬렉션에 포함할 시나리오 목록을 체크하고, 드래그 앤 드롭을 통해 실행 순서를 구성합니다.</p><p><img src="'+i+'" alt="시나리오 선택 및 순서 지정" loading="lazy"></p><hr><h2 id="_3-컬렉션-실행-모드-및-전략-비교" tabindex="-1">3. 컬렉션 실행 모드 및 전략 비교 <a class="header-anchor" href="#_3-컬렉션-실행-모드-및-전략-비교" aria-label="Permalink to “3. 컬렉션 실행 모드 및 전략 비교”">​</a></h2><p>컬렉션은 테스트 목적과 CI/CD 파이프라인 단계에 따라 두 가지 실행 모드를 선택하여 구동할 수 있습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">실행 모드</th><th style="text-align:left;">동작 방식</th><th style="text-align:center;">세션 및 쿠키 공유 여부</th><th style="text-align:left;">주요 활용 시나리오</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>순차 실행 (Sequential Mode)</strong></td><td style="text-align:left;">지정된 순서(<code>1 -&gt; 2 -&gt; 3</code>)대로 시나리오를 하나씩 실행</td><td style="text-align:center;">격리 또는 선택적 유지</td><td style="text-align:left;">스모크 테스트(Smoke Test), 선후행 데이터 의존성이 있는 업무 검증</td></tr><tr><td style="text-align:left;"><strong>병렬 실행 (Parallel Mode)</strong></td><td style="text-align:left;">다수의 Playwright 브라우저 워커에서 시나리오 및 멀티 브라우저(<code>Chromium</code>, <code>Firefox</code>, <code>WebKit</code>) 동시 구동</td><td style="text-align:center;">시나리오별 완전 격리</td><td style="text-align:left;">대규모 야간 회귀 테스트(Nightly Regression), 크로스 브라우징 호환성 검증</td></tr></tbody></table><hr><h2 id="_4-컬렉션-실행-및-결과-집계" tabindex="-1">4. 컬렉션 실행 및 결과 집계 <a class="header-anchor" href="#_4-컬렉션-실행-및-결과-집계" aria-label="Permalink to “4. 컬렉션 실행 및 결과 집계”">​</a></h2><p>컬렉션 실행 시 각 시나리오별 통과/실패 상태가 실시간으로 집계되며, 전체 컬렉션 실행 완료 후 종합 결과 리포트가 대시보드에 기록됩니다.</p>',20),o("iframe",{width:"100%",height:"400",src:"https://www.youtube.com/embed/dsb0XpGy7A0",frameborder:"0",allowfullscreen:"",allow:"autoplay; encrypted-media"},null,-1)])])}const f=e(s,[["render",d]]);export{y as __pageData,f as default};
